/bin/zsh -c "python3 -c 'import pathlib,json,hashlib,itertools
z=json.loads(pathlib.Path('\\''source/plan.json'\\'').read_text())['\\''propositions'\\''][0];target=json.loads(pathlib.Path('\\''provenance.json'\\'').read_text())['\\''approvals'\\'']['\\''P1'\\'']['\\''contract_hash'\\'']; hits=[]
for k in range(1,len(z)+1):
 for ks in itertools.combinations(z,k):
  obj={key:z[key] for key in ks}
  for sort in [True,False]:
   for ensure in [True,False]:
    for sep in [None,('\\'','\\'','\\'':'\\''),('\\'', '\\'','\\'': '\\'')]:
     for indent in [None,2]:
      s=json.dumps(obj,sort_keys=sort,ensure_ascii=ensure,separators=sep,indent=indent)
      for e in ['\\'''\\'', '\\''\\n'\\'']:
       if hashlib.sha256((s+e).encode()).hexdigest()==target:hits.append([ks,sort,ensure,sep,indent,e])
print('\\''contract hash scheme'\\'',hits)'"

