for d in range(2,math.isqrt(x)+1):sf[d*d::d*d]=False
nn=n[sf[1:]];old=json.loads(pathlib.Path('\\''source/numerics/snapshot/results.json'\\'').read_text());mp.mp.dps=60;c0=np.longdouble(str(6/mp.pi**2));err={}
for name,f,w in [('\\''k"'^2+1'"'\\'',lambda k:k*k+1,lambda k:2*k),('\\''k"'^3+2'"'\\'',lambda k:k**3+2,lambda k:3*k*k)]:
 rows=[r for r in old['\\''polynomials'\\''][name]['\\''rows'\\''] if r['\\''x'\\'']==x];ys={r['\\''y'\\'']:r for r in rows};total=np.longdouble(0);errs=[]
 for k in range(1,max(ys)+1):
  q=f(k);counts=np.bincount(nn%q,minlength=q);l=np.arange(q);fac=sympy.factorint(q);g=np.full(q,c0/q,dtype=np.longdouble)
  for p,e in fac.items():
   g*=np.longdouble(p*p)/np.longdouble(p*p-1)
